-- Rollback-only lifecycle of a simulation-based assessment (slice A1.6):
-- the COC1 M2 assessment published from the assembly-bench contract with the
-- eleven step criteria generated by scripts/publish-simulation-assessments.mjs
-- is started, recorded, submitted and evaluated by the existing attempt
-- lifecycle. A perfect action set is competent; two CPU orientation errors
-- fail the safety-critical C3; three memory reseats fail C5. Mistakes a failed
-- POST exposes still count after they are fixed (fix round 1, I2): a lever
-- closed after the POST fails C3, one missing cable fixed after a failed POST
-- keeps C9 (1 of 2), three failed POSTs on that cable fail C9. A failed run
-- charges each step once and reseating what it flagged is the repair (fix
-- round 2): a wrong DIMM pair found once keeps C5 (1 of 2), found by three
-- failed POSTs it fails C5.
--
-- The criteria JSON between the GENERATED markers is the script's output for
-- COC1 M2; after changing COC1_M2_CRITERIA, replace it with (repository root)
--   node --input-type=module -e "const m=await import('./scripts/publish-simulation-assessments.mjs');
--     console.log(JSON.stringify(m.simulationCriteria('coc1_m2',{phases:[]},
--     {moduleCode:'LO1.1',moduleTitle:'Assemble computer hardware',pcCodes:['1.4']})))"
-- (single quotes doubled for SQL).
begin;
select plan(25);

create temp table sim_ctx (
  admin uuid not null default gen_random_uuid(),
  instructor uuid not null default gen_random_uuid(),
  learner uuid not null default gen_random_uuid(),
  source uuid, module_version uuid, activity uuid, rubric uuid, class uuid, assignment uuid
) on commit drop;
insert into sim_ctx default values;
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000'::uuid, id, 'authenticated', 'authenticated',
  'simulation-lifecycle-' || id || '@bytequest.invalid', '', '{"provider":"email","providers":["email"]}'::jsonb,
  '{"full_name":"Simulation assessment rollback fixture"}'::jsonb, now(), now()
from sim_ctx cross join lateral (values (admin), (instructor), (learner)) u(id);
update public.profiles set role = 'admin' where user_id = (select admin from sim_ctx);
update public.profiles set role = 'instructor' where user_id = (select instructor from sim_ctx);

create temp table sim_rubric_source(criteria jsonb) on commit drop;
