with s as (
  insert into public.tesda_sources(qualification_code, title, edition, source_reference, status,
    validation_notes, created_by, approved_by, approved_at, activated_by, activated_at)
  select 'ROLLBACK-' || left(gen_random_uuid()::text, 8), 'Rollback-only simulation assessment source',
    'TEST_ONLY', 'Rollback fixture; never a production TESDA source', 'active', 'TEST_ONLY_ROLLBACK_FIXTURE',
    admin, admin, now(), admin, now() from sim_ctx
  returning id)
update sim_ctx set source = s.id from s;

with m as (
  insert into public.module_versions(module_id, tesda_source_id, version_number, title, source_trace,
    content_metadata, status, created_by, published_by, published_at)
  select c.id, x.source, coalesce((select max(version_number) from public.module_versions mv where mv.module_id = c.id), 0) + 1,
    'Rollback simulation assessment module',
    jsonb_build_object('source_classification', 'TEST_ONLY', 'note', 'Rollback fixture'),
    jsonb_build_object('assessment_engine', 'simulation_replay_v1'), 'draft', x.admin, null, null
  from sim_ctx x cross join public.coc_modules c where c.coc_code = 'coc1'
  returning id)
update sim_ctx set module_version = m.id from m;

-- Drafted exactly as the publish script writes it: no simulation_template, the
-- learner payload names the contract version, the evaluator holds the contract.
with a as (
  insert into public.activity_versions(mission_id, module_version_id, version_number, title, delivery_mode,
    learner_payload, evaluator_config, status, created_by, published_by, published_at)
  select ms.id, x.module_version,
    coalesce((select max(version_number) from public.activity_versions av where av.mission_id = ms.id), 0) + 1,
    'Install Internal Components — simulation assessment', 'assessment',
    jsonb_build_object('mission_id', 'coc1_m2', 'definition_version', c.version, 'mode', 'assessment'),
    jsonb_build_object('engine', 'simulation_replay_v1', 'simulation_definition', c.definition,
      'contract_version', c.version),
    'draft', x.admin, null, null
  from sim_ctx x
  cross join public.missions ms
  join public.practice_mission_contracts c on c.mission_id = ms.mission_code
  where ms.mission_code = 'coc1_m2'
  returning id)
update sim_ctx set activity = a.id from a;

with r as (
  insert into public.rubric_versions(activity_version_id, tesda_source_id, version_number, title, status, created_by)
  select activity, source, 1, 'COC1_M2 simulation step rubric', 'draft', admin from sim_ctx
  returning id)
update sim_ctx set rubric = r.id from r;
insert into public.rubric_criteria(rubric_version_id, criterion_code, title, description, source_trace,
  evidence_rule, scoring_rule, max_value, order_index, is_required)
select x.rubric, c->>'criterion_code', c->>'title', c->>'description', c->>'source_trace',
  c->'evidence_rule', c->'scoring_rule', (c->>'max_value')::numeric, (c->>'order_index')::integer,
  (c->>'is_required')::boolean
from sim_ctx x, sim_rubric_source s, jsonb_array_elements(s.criteria) c;

insert into public.activity_curriculum_links(activity_version_id, module_id, delivery_kind)
select x.activity, l.module_id, 'simulation'
from sim_ctx x join public.mission_curriculum_links l on l.mission_code = 'coc1_m2';

-- The admin publishes the module and activity and approves the generated
-- rubric through the same governed RPCs the script calls; approval validates
-- every simulation_condition rule. pgTAP runs as the owner, so the
-- authenticated calls record their outcome in temp tables first.
create temp table sim_approval(error text) on commit drop;
grant select on sim_ctx to authenticated;
grant insert on sim_approval to authenticated;
select set_config('request.jwt.claim.sub', (select admin::text from sim_ctx), true);
select set_config('request.jwt.claim.role', 'authenticated', true);
set local role authenticated;
do $$
begin
  perform public.publish_module_version((select module_version from sim_ctx),
    'Rollback publication of the simulation assessment module');
  perform public.publish_activity_version((select activity from sim_ctx),
    'Rollback publication of the COC1 M2 simulation assessment');
  perform public.approve_rubric_version((select rubric from sim_ctx), 'binary_sum',
    jsonb_build_object('status', 'APPROVED', 'method', 'all_required',
      'classification', 'PROJECT_APPROVED_OPERATIONAL_RULE', 'official_numeric_threshold', null,
      'step_threshold', 'At most two incorrect attempts per step; safety-critical steps none (owner decision 7).'),
    'Rollback approval of the generated simulation step rubric');
exception when others then
  insert into sim_approval values (sqlerrm);
end $$;
reset role;
select is((select status::text || coalesce((select ' ' || string_agg(error, ',') from sim_approval), '')
    from public.rubric_versions where id = (select rubric from sim_ctx)),
  'approved', 'the generated package publishes and its step rubric passes governed approval');

with c as (
  insert into public.classes(title, instructor_id, created_by)
  select 'Rollback simulation assessment class', instructor, instructor from sim_ctx returning id)
update sim_ctx set class = c.id from c;
insert into public.class_memberships(class_id, learner_id, enrolled_by)
select class, learner, instructor from sim_ctx;
with s as (
  insert into public.assignments(class_id, activity_version_id, rubric_version_id, assignment_type, title, assigned_by)
  select class, activity, rubric, 'assessment', 'COC1 M2 simulation assessment', instructor from sim_ctx
  returning id)
update sim_ctx set assignment = s.id from s;

create temp table sim_step(name text primary key, phase text, kind text, target text, value jsonb) on commit drop;
