-- The learner takes the assessment once per run through the normal RPCs.
select set_config('request.jwt.claim.sub', (select learner::text from sim_ctx), true);
select set_config('request.jwt.claim.role', 'authenticated', true);
set local role authenticated;
do $$
declare v_run record; v_attempt uuid;
begin
  for v_run in select name, steps from sim_run order by name loop
    select id into v_attempt from public.start_attempt((select assignment from sim_ctx), gen_random_uuid());
    for i in 1..array_length(v_run.steps, 1) loop
      perform public.append_attempt_action(v_attempt, i, s.kind, s.target,
        s.value || jsonb_build_object('phase_id', s.phase, 'mission_id', 'coc1_m2',
          'runtime_action_type', coalesce(s.value->>'runtime_action_type', s.kind),
          'client_action_id', v_run.name || '-' || i),
        clock_timestamp())
      from sim_step s where s.name = v_run.steps[i];
    end loop;
    perform public.submit_attempt(v_attempt, gen_random_uuid(), 600);
    update sim_run set attempt = v_attempt where name = v_run.name;
  end loop;
end $$;
reset role;

create function pg_temp.observation(p_run text, p_code text)
returns text language sql stable as $$
  select cr.observation::text
  from public.criterion_results cr
  join public.rubric_criteria rc on rc.id = cr.rubric_criterion_id
  where cr.attempt_id = (select attempt from sim_run where name = p_run) and rc.criterion_code = p_code
$$;
create function pg_temp.not_satisfied(p_run text)
returns text[] language sql stable as $$
  select coalesce(array_agg(rc.criterion_code order by rc.order_index), '{}')
  from public.criterion_results cr
  join public.rubric_criteria rc on rc.id = cr.rubric_criterion_id
  where cr.attempt_id = (select attempt from sim_run where name = p_run)
    and cr.observation <> 'satisfied'
$$;
create function pg_temp.outcome(p_run text)
returns text language sql stable as $$
  select sr.outcome::text from public.score_revisions sr
  where sr.attempt_id = (select attempt from sim_run where name = p_run)
    and sr.revision_type = 'automated_provisional'
$$;

select is((select count(*)::integer from public.attempts
    where id in (select attempt from sim_run) and status = 'evaluated'),
  9, 'submitting each attempt runs the server evaluation');
select is((select count(*)::integer from public.criterion_results
    where attempt_id = (select attempt from sim_run where name = 'perfect')),
  11, 'every step criterion is evaluated');
select is(pg_temp.not_satisfied('perfect'), '{}'::text[], 'a perfect action set satisfies all eleven criteria');
select is(pg_temp.outcome('perfect'), 'competent', 'a perfect action set is competent');
select is(pg_temp.observation('cpu_two_errors', 'COC1_M2_C3'), 'not_satisfied',
  'two CPU orientation errors fail the safety-critical CPU criterion');
select is(pg_temp.not_satisfied('cpu_two_errors'), array['COC1_M2_C3'],
  'the CPU errors fail no other criterion');
select is(pg_temp.outcome('cpu_two_errors'), 'not_yet_competent', 'a failed required criterion is not yet competent');
select is(pg_temp.observation('ram_three_corrections', 'COC1_M2_C5'), 'not_satisfied',
  'three memory reseats exceed the step threshold');
select is(pg_temp.not_satisfied('ram_three_corrections'), array['COC1_M2_C5'],
  'the memory reseats fail no other criterion');
select is((select cr.observed_evidence->'incorrect_by_target'->'item:ram_1'
    from public.criterion_results cr join public.rubric_criteria rc on rc.id = cr.rubric_criterion_id
    where cr.attempt_id = (select attempt from sim_run where name = 'ram_three_corrections')
      and rc.criterion_code = 'COC1_M2_C5'),
  '{"invalid": 0, "corrections": 3, "failed_checks": 0}'::jsonb, 'the evidence shows the counted corrections');
select is(pg_temp.observation('lever_after_post', 'COC1_M2_C3'), 'not_satisfied',
  'a CPU lever closed only after a failed POST fails the safety-critical CPU criterion');
select is(pg_temp.not_satisfied('lever_after_post'), array['COC1_M2_C3'],
  'the late lever fails no other criterion');
select is(pg_temp.not_satisfied('eps_after_post'), '{}'::text[],
  'one missing cable fixed after a failed POST stays within the power-cable threshold');
select is((select cr.observed_evidence->'incorrect_by_target'->'step:power_cables'
    from public.criterion_results cr join public.rubric_criteria rc on rc.id = cr.rubric_criterion_id
    where cr.attempt_id = (select attempt from sim_run where name = 'eps_after_post')
      and rc.criterion_code = 'COC1_M2_C9'),
  '{"invalid": 0, "corrections": 0, "failed_checks": 1}'::jsonb, 'the evidence shows the failed POST check');
select is(pg_temp.observation('eps_three_posts', 'COC1_M2_C9'), 'not_satisfied',
  'three failed POSTs on the same missing cable exceed the power-cable threshold');
select is(pg_temp.not_satisfied('eps_three_posts'), array['COC1_M2_C9'],
  'the repeated POST failures fail no other criterion');
create function pg_temp.c5_incorrect(p_run text)
returns integer language sql stable as $$
  select (cr.observed_evidence->>'incorrect_total')::integer
  from public.criterion_results cr join public.rubric_criteria rc on rc.id = cr.rubric_criterion_id
  where cr.attempt_id = (select attempt from sim_run where name = p_run) and rc.criterion_code = 'COC1_M2_C5'
$$;
select is(pg_temp.not_satisfied('dimm_pair_after_post'), '{}'::text[],
  'a wrong DIMM pair fixed after one failed POST keeps every criterion satisfied');
select is(pg_temp.c5_incorrect('dimm_pair_after_post'), 1,
  'the failed POST costs the memory step one attempt; the reseats are the repair');
select is(pg_temp.not_satisfied('dimm_pair_three_posts'), array['COC1_M2_C5'],
  'the same wrong pair found by three failed POSTs counts three times and fails only C5');
select is(pg_temp.not_satisfied('memory_two_faults_one_post'), '{}'::text[],
  'open latches and a wrong pair found by one failed POST keep the memory step satisfied');
select is(pg_temp.c5_incorrect('memory_two_faults_one_post'), 1,
  'two failing memory checks in one POST charge the step once');
select is((select cr.expected_rule->'evidence_rule'->>'operator'
    from public.criterion_results cr join public.rubric_criteria rc on rc.id = cr.rubric_criterion_id
    where cr.attempt_id = (select attempt from sim_run where name = 'perfect') and rc.criterion_code = 'COC1_M2_C1'),
  'simulation_condition', 'criterion results record the simulation rule they applied');
select is((select delivery_kind from public.activity_curriculum_links where activity_version_id = (select activity from sim_ctx)),
  'simulation', 'the assessment is placed in its curriculum module as a simulation');
select ok(not ((select learner_payload from public.activity_versions where id = (select activity from sim_ctx)) ? 'simulation_template'),
  'the learner payload opens the shared simulation, not a form template');

select * from finish();
rollback;
